function ThemeButton({theme,setTheme}) { return <button className="icon-button" aria-label="Alternar tema" onClick={()=>setTheme(theme==='dark'?'light':'dark')}>{theme==='dark'?<Sun1/>:<Moon/>}</button> }

function Login({onLogin, theme, setTheme}) {
  const [password,setPassword]=useState(''); const [email,setEmail]=useState('acartomantereal@gmail.com');
  const [show,setShow]=useState(false); const [error,setError]=useState(''); const [loading,setLoading]=useState(false);
  const submit=async(e)=>{e.preventDefault();setError('');setLoading(true);if(!supabaseConfigured){setError('Supabase não configurado. Verifique as variáveis de ambiente.');setLoading(false);return}const {error:authError}=await supabase.auth.signInWithPassword({email:email.trim().toLowerCase(),password:password.trim()});if(authError){setError(authError.status===400?'E-mail ou senha incorretos.':'Não foi possível acessar o servidor de autenticação. Tente novamente.');setLoading(false);return}onLogin?.()};
  return <main className="login-shell">
    <section className="login-story">
      <div className="brand"><span className="brand-mark"><Message variant="Bold"/></span><b>manysend</b></div>
      <div className="story-copy"><span className="eyebrow"><ShieldTick/> AUTOMAÇÃO OFICIAL E SEGURA</span><h1>Conversas que continuam, mesmo quando você sai.</h1><p>Gerencie seus canais, crie jornadas e transforme respostas em relacionamento — em um único lugar.</p></div>
      <div className="signal-card"><div><span className="live-dot"/><b>Fluxo em execução</b><small>Boas-vindas · Instagram</small></div><span className="result">+28,4% <TrendUp/></span></div>
      <small className="legal">APIs oficiais · Controles de consentimento · Dados protegidos</small>
    </section>
    <section className="login-panel"><div className="theme-float"><ThemeButton theme={theme} setTheme={setTheme}/></div><form onSubmit={submit}>
      <span className="mobile-brand">manysend</span><h2>Bem-vindo de volta</h2><p className="muted">Entre no painel da sua operação.</p>
      <label>E-mail<input value={email} onChange={e=>setEmail(e.target.value)} type="email" autoComplete="username" placeholder="admin@empresa.com"/></label>
      <label>Senha<div className="password"><input value={password} onChange={e=>setPassword(e.target.value)} type={show?'text':'password'} autoComplete="current-password" placeholder="Sua senha"/><button type="button" onClick={()=>setShow(!show)} aria-label={show?'Ocultar senha':'Mostrar senha'}>{show?<EyeSlash/>:<Eye/>}</button></div></label>
      <div className="form-row"><label className="check"><input type="checkbox"/> Manter conectado</label><button type="button" className="link">Esqueci minha senha</button></div>
      {error&&<div className="error"><CloseCircle/>{error}</div>}
      <button className="primary login-button" disabled={loading}>{loading?<span className="loading-line">Validando acesso</span>:<>Entrar no painel <ArrowRight2/></>}</button>
      <p className="support">Problemas para acessar? <button type="button" className="link">Falar com suporte</button></p>
    </form></section>
  </main>
}

function Stat({label,value,delta,sub}) {return <div className="stat"><span>{label}</span><div><strong>{value}</strong><em><TrendUp/> {delta}</em></div><small>{sub}</small></div>}
function AudienceOverview(){
  const [syncing,setSyncing]=useState(true); const [items,setItems]=useState([]); const [loadError,setLoadError]=useState('');
  const iconMap={instagram:Instagram,facebook:Message,youtube:VideoPlay,tiktok:Flash};
  const nameMap={instagram:'Instagram',facebook:'Facebook',youtube:'YouTube',tiktok:'TikTok'};
  const load=async()=>{setSyncing(true);setLoadError('');const {data:accounts,error:accountsError}=await supabase.from('social_accounts').select('id,platform,display_name,username,status,last_synced_at').in('platform',['instagram','facebook','youtube','tiktok']);if(accountsError){setLoadError('Não foi possível consultar as contas conectadas.');setSyncing(false);return}const ids=(accounts||[]).map(x=>x.id);let metrics=[];if(ids.length){const {data,error}=await supabase.from('audience_metrics').select('social_account_id,followers,reach,captured_at').in('social_account_id',ids).order('captured_at',{ascending:false});if(error){setLoadError('As contas foram carregadas, mas as métricas estão indisponíveis.')}else metrics=data||[]}setItems((accounts||[]).map(account=>{const metric=metrics.find(x=>x.social_account_id===account.id);return {...account,followers:metric?.followers??0,reach:metric?.reach??null,captured_at:metric?.captured_at}}));setSyncing(false)};
  useEffect(()=>{if(supabase)load()},[]);
  const total=useMemo(()=>items.reduce((sum,item)=>sum+Number(item.followers||0),0),[items]);
  const format=(value)=>new Intl.NumberFormat('pt-BR').format(value);
  return <section className="audience-overview">
    <div className="audience-summary">
      <div className="audience-heading"><span className="audience-icon"><People variant="Bold"/></span><div><span>AUDIÊNCIA CONSOLIDADA</span><h2>{format(total)}</h2><p>seguidores e inscritos em todas as plataformas</p></div></div>
      <div className="audience-sync"><span>{items.length?'Dados das APIs oficiais':'Nenhuma conta conectada'}</span><small>{syncing?'Consultando plataformas…':items[0]?.captured_at?`Atualizado ${new Date(items[0].captured_at).toLocaleString('pt-BR')}`:'Aguardando primeira sincronização'}</small><button className="secondary" onClick={load} disabled={syncing}><TrendUp/>{syncing?'Sincronizando':'Sincronizar'}</button></div>
    </div>
    <div className="audience-platforms">
      {items.map(item=>{const Icon=iconMap[item.platform]||Grid5;return <article className="audience-platform" key={item.id}><div className="platform-identity"><span className={`platform-mark ${item.platform}`}><Icon variant="Bold"/></span><div><b>{nameMap[item.platform]||item.platform}</b><small>{item.username||item.display_name||'Conta conectada'}</small></div></div><div className="platform-metrics"><div><span>{item.platform==='youtube'?'Inscritos':'Seguidores'}</span><strong>{format(item.followers)}</strong></div><div className={item.reach===null?'unavailable':''}><span>Alcance</span><strong>{item.reach===null?'—':format(item.reach)}</strong>{item.reach===null&&<small>Não disponibilizado pela API</small>}</div></div></article>})}
      {!syncing&&!items.length&&<div className="audience-empty"><Grid5/><div><b>Conecte suas contas sociais</b><p>As métricas reais aparecerão após autorizar Meta, YouTube ou TikTok em Configurações.</p></div></div>}
      {loadError&&<div className="audience-empty error-state"><CloseCircle/><div><b>Falha na sincronização</b><p>{loadError}</p></div></div>}
    </div>
    <div className="audience-foot"><ShieldTick/><p>O total soma somente seguidores e inscritos. O alcance permanece separado porque cada API processa essa métrica de forma diferente.</p><button className="text-button">Últimos 30 dias <ArrowDown2/></button></div>
  </section>
}
function MiniChart(){return <div className="chart"><div className="chart-head"><div><span>Conversas iniciadas</span><strong>8.429</strong></div><select><option>Últimos 30 dias</option></select></div><div className="bars">{[34,51,39,70,52,78,63,88,68,91,77,96].map((h,i)=><i key={i} style={{height:`${h}%`}}><span>{[310,462,359,641,487,718,589,803,633,847,721,892][i]}</span></i>)}</div><div className="axis"><span>01 Jul</span><span>08 Jul</span><span>15 Jul</span><span>22 Jul</span><span>30 Jul</span></div></div>}

