 return <div className="account-select">{data.map(([key,name,handle,I])=><button key={key} className={channelsPost[key]?'selected':''} onClick={()=>toggleChannel(key)}><span className="social-logo"><I variant="Bold"/></span><div><b>{name}</b><small>{handle}</small></div><i>{channelsPost[key]&&<TickCircle variant="Bold"/>}</i></button>)}</div>
