function SafeCampaigns(){
 const [active,setActive]=useState(true); const [channel,setChannel]=useState('Instagram');
 return <><div className="page-title"><div><span className="eyebrow">DISTRIBUIÇÃO COM CONSENTIMENTO</span><h1>Campanhas</h1><p>Envie novidades somente para pessoas que autorizaram mensagens.</p></div><button className="primary"><Add/> Nova campanha</button></div><div className="compliance-banner"><ShieldTick/><div><b>Proteções de plataforma ativadas</b><p>Opt-in obrigatório, descadastro imediato, limites por canal e bloqueio de mensagens fora das regras.</p></div><span>6 REGRAS ATIVAS</span></div><div className="safe-campaign-layout"><section className="campaign-builder"><div className="section-head"><div><h3>Novo vídeo → DM autorizada</h3><p>Fluxo pré-configurado para a Vovó Tereza</p></div><label className="switch"><input type="checkbox" checked={active} onChange={()=>setActive(!active)}/><i/></label></div><div className="builder-step"><span>1</span><div><b>Quando isso acontecer</b><small>Selecione o evento que iniciará a campanha.</small><label>Gatilho<select defaultValue="Novo vídeo publicado"><option>Novo vídeo publicado</option><option>Novo Reel publicado</option><option>Nova receita no site</option></select></label><label>Origem<select defaultValue="Qualquer conta conectada"><option>Qualquer conta conectada</option><option>Instagram</option><option>YouTube</option><option>TikTok</option></select></label></div></div><div className="builder-line"/><div className="builder-step"><span>2</span><div><b>Quem poderá receber</b><small>A campanha nunca inclui pessoas sem consentimento válido.</small><div className="audience-rules"><label><TickCircle variant="Bold"/><span><b>Consentimento de DM ativo</b><small>Obrigatório · não pode ser removido</small></span></label><label><TickCircle variant="Bold"/><span><b>Interesse relacionado ao vídeo</b><small>Tags: receitas naturais, sem açúcar</small></span></label><label><CloseCircle/><span><b>Excluir descadastrados e bloqueados</b><small>Sincronizado antes de cada envio</small></span></label></div><div className="audience-count"><People/><span><b>3.842 pessoas elegíveis</b><small>de 24.891 contatos cadastrados</small></span></div></div></div><div className="builder-line"/><div className="builder-step"><span>3</span><div><b>Mensagem enviada</b><small>O link é preenchido automaticamente com o vídeo publicado.</small><div className="channel-pills">{['Instagram','WhatsApp','Messenger'].map(x=><button className={channel===x?'active':''} onClick={()=>setChannel(x)} key={x}>{x}</button>)}</div><label className="campaign-message">Mensagem<textarea defaultValue={'Oi, {{primeiro_nome}}. A Vovó Tereza acabou de publicar uma receita nova que combina com seus interesses.\n\n{{titulo_video}}\n{{link_video}}\n\nSe não quiser mais receber novidades, responda SAIR.'}/><span>Variáveis verificadas</span></label><div className="variable-chips"><button>{'{{primeiro_nome}}'}</button><button>{'{{titulo_video}}'}</button><button>{'{{link_video}}'}</button></div></div></div><div className="builder-line"/><div className="builder-step"><span>4</span><div><b>Controles de entrega</b><small>Regras aplicadas antes de cada mensagem.</small><div className="delivery-grid"><label>Intervalo mínimo<select defaultValue="7 dias"><option>7 dias por contato</option><option>14 dias por contato</option><option>30 dias por contato</option></select></label><label>Horário permitido<select defaultValue="9"><option>09:00 às 19:00</option><option>10:00 às 18:00</option></select></label><label>Velocidade<select defaultValue="Conservadora"><option>Conservadora</option><option>Moderada</option></select></label><label>Em caso de limite<select defaultValue="Pausar"><option>Pausar e reagendar</option><option>Cancelar restante</option></select></label></div></div></div><div className="campaign-actions"><button className="secondary"><Eye/> Simular campanha</button><button className="primary">Revisar e ativar <ArrowRight2/></button></div></section><aside className="campaign-safety"><div className="section-head"><div><h3>Verificação de segurança</h3><p>Atualizada em tempo real</p></div></div>{[['Consentimento registrado','Apenas contatos com opt-in verificável'],['Link associado ao conteúdo','URL obtida da postagem publicada'],['Janela e frequência','Sem mensagens repetitivas ou noturnas'],['Descadastro automático','SAIR remove o contato imediatamente'],['Limites oficiais','Envio pausado antes de exceder cotas'],['Conteúdo permitido','Sem scraping ou mensagens não solicitadas']].map((x,i)=><div className="safety-check" key={x[0]}><TickCircle variant="Bold"/><span><b>{x[0]}</b><small>{x[1]}</small></span></div>)}<div className="rule-note"><ShieldTick/><p>Uma campanha será bloqueada se perder consentimento, exceder a janela permitida ou não tiver template aprovado quando exigido.</p></div></aside></div><section className="campaign-history"><div className="section-head"><div><h3>Campanhas recentes</h3><p>Envios e interrupções registrados para auditoria</p></div></div>{[['Receita nova · Bolo de banana','Instagram','3.104','Concluída'],['Vídeo novo · Café da manhã','WhatsApp','1.287','Concluída'],['Receita semanal · Sucos','Messenger','—','Pausada por limite']].map(x=><div className="history-row" key={x[0]}><span className="event-icon"><Sms/></span><div><b>{x[0]}</b><small>{x[1]}</small></div><span><small>Entregues</small><b>{x[2]}</b></span><span className={x[3].includes('Pausada')?'paused':'status'}><i/>{x[3]}</span><button><ArrowRight2/></button></div>)}</section></>;
}

